// Get returns the record addressed by its resource name.
func (r *GraphQLPolicyRepository) Get(ctx context.Context, name string) (*policyv1.Policy, error) {
	row, err := r.find(ctx, name)
	if err != nil {
		return nil, err
	}
	return r.toProto(ctx, row, nil)
}

// rowID returns the surrogate key of the row named name, looked up by name:
// the id is unique only under the parent, so it is not the key.
// repox.ErrNotFound when there is no such row.
func (r *GraphQLPolicyRepository) rowID(ctx context.Context, name string) (string, error) {
	row, err := r.find(ctx, name)
	if err != nil {
		return "", err
	}
	return row.Id, nil
}

// find reads the row named name; repox.ErrNotFound when there is none.
func (r *GraphQLPolicyRepository) find(ctx context.Context, name string) (*policiesql.PolicyPolicies, error) {
	if _, err := repox.SplitName(name, "hotels", "policies"); err != nil {
		return nil, err
	}
	row, err := r.Svc.Query.Policy.Policies.Find(ctx, policiesql.List().Where(policiesql.Name.Eq(name)))
	if err != nil {
		return nil, mapGraphQLErr(err)
	}
	if row == nil {
		return nil, repox.ErrNotFound
	}
	return row, nil
}

// get loads by surrogate key — the private read every generated method
// re-reads through.
func (r *GraphQLPolicyRepository) get(ctx context.Context, id string) (*policyv1.Policy, error) {
	row, err := r.Svc.Query.Policy.Policies.Get(ctx, id)
	if err != nil {
		return nil, mapGraphQLErr(err)
	}
	if row == nil {
		return nil, repox.ErrNotFound
	}
	return r.toProto(ctx, row, nil)
}

