// List returns one page of records under parent.
func (r *GraphQLPolicyRepository) List(ctx context.Context, parent string, in repox.ListInput) ([]*policyv1.Policy, string, error) {
	parentIDs, err := repox.SplitName(parent, "hotels")
	if err != nil {
		return nil, "", err
	}
	// AIP-159: "-" for the parent reads across every parent.
	if parentIDs[len(parentIDs)-1] == "-" {
		return r.list(ctx, in)
	}
	return r.list(ctx, in, policiesql.HotelId.Eq(parentIDs[len(parentIDs)-1]))
}

func (r *GraphQLPolicyRepository) list(ctx context.Context, in repox.ListInput, scope ...graphql.Predicate) ([]*policyv1.Policy, string, error) {
	if !in.ShowDeleted {
		scope = append(scope, policiesql.DeleteTime.IsNull(true))
	}
	conds, err := filterx.Parse(in.Filter)
	if err != nil {
		return nil, "", repox.MapFilterxErr(err)
	}
	conds = append(conds, in.Where...)
	if err := repox.CheckReadMask((*policyv1.Policy)(nil), in.ReadMask); err != nil {
		return nil, "", err
	}
	eng := filterx.Hasura[policiesql.PolicyPolicies](policy.PolicyFilterSpec, r.Svc.Query.Policy.Policies).Scope(scope...)
	for f, h := range r.ListOverrides {
		eng.Override(f, h)
	}
	eng.Via("cancel_policy", func(ctx context.Context, keys []string, where graphql.Predicate) ([]string, error) {
		rows, err := r.Svc.Query.Policy.CancelPenalties.List(ctx, cancelpenaltiesql.List().Where(graphql.And(cancelpenaltiesql.Id.In(keys...), where)))
		ids := make([]string, 0, len(rows))
		for i := range rows {
			ids = append(ids, rows[i].Id)
		}
		return ids, err
	})
	eng.Via("guarantee_payment_policy", func(ctx context.Context, keys []string, where graphql.Predicate) ([]string, error) {
		rows, err := r.Svc.Query.Policy.GuaranteePaymentPolicies.List(ctx, guaranteepaymentpoliciesql.List().Where(graphql.And(guaranteepaymentpoliciesql.Id.In(keys...), where)))
		ids := make([]string, 0, len(rows))
		for i := range rows {
			ids = append(ids, rows[i].Id)
		}
		return ids, err
	})
	eng.Via("pets_policies", func(ctx context.Context, keys []string, where graphql.Predicate) ([]string, error) {
		rows, err := r.Svc.Query.Policy.PetsPolicies.List(ctx, petspoliciesql.List().Where(graphql.And(petspoliciesql.Id.In(keys...), where)))
		ids := make([]string, 0, len(rows))
		for i := range rows {
			ids = append(ids, rows[i].Id)
		}
		return ids, err
	})
	eng.Via("start", func(ctx context.Context, keys []string, where graphql.Predicate) ([]string, error) {
		rows, err := r.Svc.Query.Policy.DateOrTimeOrDateTimes.List(ctx, dateortimeordatetimesql.List().Where(graphql.And(dateortimeordatetimesql.Id.In(keys...), where)))
		ids := make([]string, 0, len(rows))
		for i := range rows {
			ids = append(ids, rows[i].Id)
		}
		return ids, err
	})
	eng.Via("end", func(ctx context.Context, keys []string, where graphql.Predicate) ([]string, error) {
		rows, err := r.Svc.Query.Policy.DateOrTimeOrDateTimes.List(ctx, dateortimeordatetimesql.List().Where(graphql.And(dateortimeordatetimesql.Id.In(keys...), where)))
		ids := make([]string, 0, len(rows))
		for i := range rows {
			ids = append(ids, rows[i].Id)
		}
		return ids, err
	})
	eng.Via("policy_info", func(ctx context.Context, keys []string, where graphql.Predicate) ([]string, error) {
		rows, err := r.Svc.Query.Policy.Infos.List(ctx, infosql.List().Where(graphql.And(infosql.Id.In(keys...), where)))
		ids := make([]string, 0, len(rows))
		for i := range rows {
			ids = append(ids, rows[i].Id)
		}
		return ids, err
	})
	eng.Via("commission_policy", func(ctx context.Context, keys []string, where graphql.Predicate) ([]string, error) {
		rows, err := r.Svc.Query.Policy.CommissionPolicies.List(ctx, commissionpoliciesql.List().Where(graphql.And(commissionpoliciesql.Id.In(keys...), where)))
		ids := make([]string, 0, len(rows))
		for i := range rows {
			ids = append(ids, rows[i].Id)
		}
		return ids, err
	})
	rows, next, err := eng.List(ctx, filterx.ListInput{
		PageSize:  in.PageSize,
		PageToken: in.PageToken,
		OrderBy:   in.OrderBy,
		Filter:    conds,
	})
	if err != nil {
		return nil, "", repox.MapFilterxErr(err)
	}
	items := make([]*policyv1.Policy, 0, len(rows))
	for i := range rows {
		out, err := r.toProto(ctx, &rows[i], in.ReadMask)
		if err != nil {
			return nil, "", err
		}
		repox.Narrow(out, in.ReadMask)
		items = append(items, out)
	}
	return items, next, nil
}

// Update persists the masked fields of in; an empty mask replaces every
